def pth(p):return str(p.relative_to(ROOT))
inputs=load(pth(O/'audit_inputs.json'));diags={c['case_id']:c for c in load(pth(O/'source_diagnostics.json'))['cases']};allcopies={c['case_id']:c for c in load(pth(O/'all_copy_diagnostics.json'))['cases']};assemblies={c['case_id']:c for c in load(pth(O/'assembly_context.json'))['cases']};manual=load(pth(O/'manual_adjudications.json'))
