 p=e['pdb_id'];d=diags[p];adj=manual['decisions'][p];ass=assemblies[p];co=allcopies[p];selected,scope=qualified_component(d,adj['full_original_reagent_complete']);selected=list(selected);wanted={canonical_atom_key(a) for r in d['residues'] if r['branch_num'] in selected for a in r['atom_map']};scored=[deepcopy(a) for a in d['native_atom_map'] if canonical_atom_key(a) in wanted]
