for c in ledger['cases']:print(c['case_id'],c['qualification'],c['scored_residue_ids'],c['scored_atom_count'],'copies',len(c['qualified_copies']),'prepare',c['source_conditioned_preparation_eligible'])
print('ledgerSHA',sha('benchmarks/heldout_reference_ledger.json'))
